use crate::session_import::mobaxterm_crypto::{SecretContext, decode_plaintext, decrypt};

// Synthetic vectors generated independently with Python hashlib and
// cryptography AES-ECB/AES-CFB8; weak vectors generated by a separate script.
const LEGACY: &str = "Lw+8ew2leHRCfHlGFP0SMA==";
const V25: &str = "_@QWERTYUIOPASDFGHJKITPTpQ1TPIVVjBQhlq_7cQ==";

#[test]
fn master_formats_decrypt_independent_vectors_and_trailing_nul_padding() {
    for ciphertext in [LEGACY, V25, "Lw+8ew2leHRCfHlGFP0SMKZo"] {
        let secret = decrypt(
            ciphertext,
            &SecretContext {
                master_password: Some("synthetic-master"),
                ..SecretContext::default()
            },
        )
        .unwrap();
        assert_eq!(secret.expose_secret(), "synthetic-import");
        assert!(!format!("{secret:?}").contains("synthetic-import"));
    }
}

#[test]
fn master_and_secret_preserve_whitespace_and_unicode() {
    for ciphertext in ["f0MatmWHE9N2OQsC", "_@QWERTYUIOPASDFGHJKTIwfJD7ARab2joRj"] {
        let secret = decrypt(
            ciphertext,
            &SecretContext {
                master_password: Some(" synthetic master "),
                ..SecretContext::default()
            },
        )
        .unwrap();
        assert_eq!(secret.expose_secret(), " 密码\t☃ ");
        assert!(
            decrypt(
                ciphertext,
                &SecretContext {
                    master_password: Some("synthetic master"),
                    ..SecretContext::default()
                }
            )
            .is_none()
        );
    }
}

#[test]
fn weak_session_and_connection_keys_decrypt_independent_vectors() {
    let session = decrypt(
        "TtIHsyiSS+EECsEITeEOeyIOCieEtstC",
        &SecretContext {
            session_p: Some("synthetic-session-p"),
            ..SecretContext::default()
        },
    )
    .unwrap();
    assert_eq!(session.expose_secret(), "synthetic-import");
    let connection = decrypt(
        "TsIO/yxDDrSSR/SITeSYeyIYRxeSs/sR",
        &SecretContext {
            system_username: Some("synthetic-user"),
            system_hostname: Some("synthetic-pc"),
            username: Some("deploy"),
            hostname: Some("server.example"),
            ..SecretContext::default()
        },
    )
    .unwrap();
    assert_eq!(connection.expose_secret(), "synthetic-import");
}

#[test]
fn incorrect_password_and_malformed_ciphertext_are_rejected() {
    for master in ["wrong-password", "wrong0", "wrong25", "x", "0"] {
        for ciphertext in [LEGACY, V25] {
            assert!(
                decrypt(
                    ciphertext,
                    &SecretContext {
                        master_password: Some(master),
                        ..SecretContext::default()
                    }
                )
                .is_none()
            );
        }
    }
    for ciphertext in [
        "",
        "!!!",
        "_@",
        "_@QWERTYUIOPASDFGHJK",
        "_@坏格式",
        "AA=A",
        "Lw+8ew2leHRCfHlGFP0SM",
    ] {
        assert!(
            decrypt(
                ciphertext,
                &SecretContext {
                    master_password: Some("synthetic-master"),
                    ..SecretContext::default()
                }
            )
            .is_none()
        );
    }
    assert!(
        decrypt(
            "T",
            &SecretContext {
                session_p: Some("synthetic-session-p"),
                ..SecretContext::default()
            }
        )
        .is_none()
    );
}

#[test]
fn plaintext_validation_rejects_internal_nul_controls_and_invalid_utf8() {
    for bytes in [
        b"".as_slice(),
        b"\0",
        b"prefix\0suffix",
        b"prefix\n",
        &[0xff],
        &[0x7f, 0xff],
    ] {
        assert!(decode_plaintext(bytes).is_none());
    }
    assert_eq!(
        decode_plaintext(b" prefix\t \0\0").unwrap().expose_secret(),
        " prefix\t "
    );
}
